#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25 23:45 — inserted before TASK 4 (Fatih: TASK 4 is 4th because TASK 3 may find bugs):
# (a) the 1c shim-cost sessions whose names come from the container clock (UTC, 1 h behind the host since the DST switch) and were
#     skipped by queue1e's host-time filter; (b) the eight synthetic families again with the FISH fixes of the night
#     (same-topic double subscription, hold released inside the publishing instance, source-only candidates, static step after the build).
set -u; cd "$(dirname "$0")/.."
LD=$HOME/fish_traces/night_20261025_final; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/queue.log"; }
while ! grep -q "SCALE RUNS DONE" "$LD/synth_scale.log" 2>/dev/null; do sleep 120; done
log "5: 1c pipelines (container-clock session names) + family re-runs (host off)"
for S in fish_20261025_190123 fish_20261025_191310 fish_20261025_192832 fish_20261025_193659 fish_20261025_195107 fish_20261025_200311; do
  grep -q "^$S$" "$LD/pipelines_done.txt" 2>/dev/null && continue
  [ -f "$LD/STOP" ] && { log "STOP"; break; }
  log "pipeline $S"; bash scripts/post_run_pipeline.sh "$S" "$HOME/fish_traces/analysis_$S" > "$LD/pipeline_$S.log" 2>&1 || log "pipeline $S FAILED"
  echo "$S" >> "$LD/pipelines_done.txt"
done
log "5: scale sessions re-analysed with the fixed code (no new runs; log synth_scale2.log)"
for pair in er50:synth_er_n50_s1 layered100:synth_layered_n100_s1 er200:synth_er_n200_s1 ba500:synth_ba_n500_s1; do
  N=${pair%%:*}; NAME=${pair##*:}; [ -f "$LD/STOP" ] && { log "STOP"; break; }
  # 2026-10-26: was synth_$N.log (no such file) -> the step logged "no session" and was skipped; redone by night_scale2_reanalyze_20261026.sh
  S=$(grep -h "^\[synth\] session" "$LD/synth_${N}_s1.log" 2>/dev/null | tail -1 | awk '{print $3}'); [ -n "$S" ] || { echo "[$(date +%T)] $N: no session" >> "$LD/synth_scale2.log"; continue; }
  echo "[$(date +%T)] reanalyze $N $S" >> "$LD/synth_scale2.log"
  bash tests/synth/reanalyze_synth.sh tests/synth/generated/${N}_s1.json "$S" > "$LD/reanalyze_$N.log" 2>&1
  echo "[$(date +%T)]   $N: $(grep -h VERDICT "$HOME/fish_traces/synth_runs/verify_$NAME.txt" 2>/dev/null | tail -1) $(grep -h 'false positives' "$HOME/fish_traces/synth_runs/verify_$NAME.txt" 2>/dev/null | tail -1 | cut -c1-110)" >> "$LD/synth_scale2.log"
done
log "5: family re-runs (log synth_loop2.log)"
log2() { echo "[$(date +%T)] $*" | tee -a "$LD/synth_loop2.log"; }
for D in tests/synth/generated/{chain,tree,star,bipartite,layered,er,ba,cycle}_s1.json; do
  [ -f "$D" ] || continue; [ -f "$LD/STOP" ] && { log2 "STOP"; break; }; N=$(basename "$D" .json)
  log2 "cycle $N"; bash tests/synth/run_synth.sh "$D" > "$LD/synth2_$N.log" 2>&1
  NAME=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['name'])" "$D")
  V=$(grep -h "VERDICT" "$HOME"/fish_traces/synth_runs/verify_${NAME}.txt 2>/dev/null | tail -1)
  log2 "  $N: ${V:-no verdict} $(grep -h 'false positives' "$HOME"/fish_traces/synth_runs/verify_${NAME}.txt 2>/dev/null | tail -1 | cut -c1-120)"
done
log2 "FAMILY RERUN DONE"
log "PRE-TASK4 DONE"
